use xiom.io;
fn main() -> Int {
  let nums: Vec[Int] = Vec[Int].new();
  nums.push(10);
  nums.push(20);
  nums.push(30);

  match nums.get(0) {
    Some(v) => io.println(v.to_str());
    None => io.println("missing");
  }

  match nums.get(5) {
    Some(v) => io.println(v.to_str());
    None => io.println("missing");
  }

  io.println(nums.len().to_str());
  return 0;
}
